while (true) {
    if (item < cur->val) {
        if (cur->left) {
            cur = cur->left;
        } else {
            cur->left = new TreeNode(item);
            break;
        }
    } else {
        if (cur->right) {
            cur = cur->right;
        } else {
            cur->right = new TreeNode(item);
            break;
        }
    }
}

